type StudioHttpInput = Omit<ApiEntry, 'kind' | 'project' | 'implementationStatus' | 'verifiedCommit' | 'officialSources'> & {
  officialSources?: ApiEntry['officialSources']
}

function defineStudioHttp(input: StudioHttpInput): ApiEntry {
  return {
    ...input,
    kind: 'http', project: 'ai-interview', implementationStatus: 'production', verifiedCommit: AI_INTERVIEW_COMMIT,
    officialSources: [hono, owasp, ...(input.officialSources ?? [])],
  }
}

